#!/bin/bash
# Build a transfer bundle of the OpenStock project for moving it to another Mac.
#
# The bundle carries the working tree AND the .git folder, so the destination
# machine gets the full history and the four unpushed commits. That means the
# destination can `git push origin main` on its own — no re-download, no
# conflicts, no hand-copying of files.
#
# node_modules, .next and other build output are excluded on purpose: they are
# regenerated by `npm install` / `npm run dev` on the other machine, and they
# are 760 MB of the 770 MB total.
#
# Usage:  ./make-bundle.sh [output-dir]
set -euo pipefail

PROJECT="/Users/mishalajmi/Documents/Default Project/OpenStock"
OUT_DIR="${1:-$HOME/Desktop}"
STAMP="$(date +%Y%m%d-%H%M%S)"
BUNDLE="OpenStock-${STAMP}.tar.gz"

cd "$PROJECT"

echo "==> Checking the working tree"
if ! git diff --quiet || ! git diff --cached --quiet || [ -n "$(git ls-files --others --exclude-standard)" ]; then
    echo "    Uncommitted changes detected:"
    git status --short | sed 's/^/      /'
    echo "    Committing them first so nothing is left behind."
    git add -A
    git commit -q -m "Bundle snapshot: sync local work before transferring to the other Mac" || echo "    (nothing to commit)"
fi

echo "==> Building the bundle"
mkdir -p "$OUT_DIR"

# -C: the archive paths are relative to the project root, so extracting it
# reproduces "OpenStock/..." rather than the full absolute path.
tar -czf "$OUT_DIR/$BUNDLE" \
    --exclude='./node_modules' \
    --exclude='./.next' \
    --exclude='./out' \
    --exclude='./build' \
    --exclude='./coverage' \
    --exclude='./.DS_Store' \
    --exclude='*.log' \
    -C "$(dirname "$PROJECT")" \
    "$(basename "$PROJECT")"

SIZE=$(du -h "$OUT_DIR/$BUNDLE" | cut -f1)
SHA=$(shasum -a 256 "$OUT_DIR/$BUNDLE" | cut -d' ' -f1)

cat > "$OUT_DIR/${BUNDLE%.tar.gz}.sha256" <<EOF
$SHA  $BUNDLE
EOF

echo
echo "==> Done"
echo "    Bundle : $OUT_DIR/$BUNDLE"
echo "    Size   : $SIZE"
echo "    SHA256 : $SHA"
echo
echo "Next steps on the OTHER Mac:"
echo "  1. Move the .tar.gz across (AirDrop, USB, or a shared folder)."
echo "  2. Run:  tar -xzf $BUNDLE -C \"\$HOME/Documents/Default Project\""
echo "  3. Run:  cd \"\$HOME/Documents/Default Project/OpenStock\" && npm install"
echo "  4. Run:  git push origin main     (publishes the pending commits)"
echo "  5. Run:  npm run dev"
